const $=id=>document.getElementById(id);let token='',epoch=0;
const labels={requests:'Demandes',crm:'Opportunités',consultants:'Consultants',tenders:'Appels d’offres',quotes:'Devis'};
let controlData=null;
const metrics=[['budget_revenue','CA budget'],['budget_cost','Coût budget'],['validated_revenue','Facturable validé'],['validated_cost','Coût validé'],['validated_margin','Marge opérationnelle'],['cost_remaining','Solde budget coûts'],['revenue_gap','Écart CA'],['invoiced','Créances émises'],['received','Encaissé'],['receivable','À encaisser'],['overdue','En retard'],['unbilled','Non facturé']];
function notice(s){$('notice').textContent=s}
function elem(tag,text){const e=document.createElement(tag);e.textContent=text;return e}
function renderControl(){const root=$('control-tables');root.replaceChildren();if(!controlData)return;const currency=$('control-currency').value,q=$('control-search').value.trim().toLocaleLowerCase('fr');for(const [title,items,keys] of [['Synthèse par devise',controlData.currencies,[['currency','Devise']]],['Rentabilité par client',controlData.clients,[['client','Client'],['currency','Devise']]],['Rentabilité par mission',controlData.missions,[['client','Client'],['title','Mission'],['currency','Devise']]]]){root.append(elem('h3',title));const wrap=document.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr'),body=document.createElement('tbody');for(const [,label] of [...keys,...metrics]){const th=elem('th',label);th.scope='col';tr.append(th)}thead.append(tr);table.append(thead,body);for(const x of items){if(currency&&x.currency!==currency)continue;if(q&&x.client&&!((x.client+' '+(x.title||'')).toLocaleLowerCase('fr').includes(q)))continue;const r=document.createElement('tr');for(const [k] of [...keys,...metrics])r.append(elem('td',x[k]));body.append(r)}if(!body.children.length){const r=document.createElement('tr'),td=elem('td','Aucun résultat.');td.colSpan=keys.length+metrics.length;r.append(td);body.append(r)}wrap.append(table);root.append(wrap)}renderSupplement(root,currency,q);}
function renderSupplement(root,currency,q){for(const [title,items,keys] of [['Flux de trésorerie enregistrés',controlData.cash,[['currency','Devise'],['received','Entrées'],['outflows','Sorties'],['net_flow','Flux net']]],['Analyse individuelle des consultants',controlData.consultants,[['consultant','Consultant'],['title','Mission'],['currency','Devise'],['worked','Jours travaillés'],['billable','Jours facturables'],['cost','Coût direct'],['revenue','CA facturable'],['margin','Marge régie']]]]){root.append(elem('h3',title));const wrap=document.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr'),body=document.createElement('tbody');for(const [,label] of keys){const th=elem('th',label);th.scope='col';tr.append(th)}head.append(tr);table.append(head,body);for(const x of items){if(currency&&x.currency!==currency)continue;if(q&&x.consultant&&!(x.consultant+' '+x.title).toLocaleLowerCase('fr').includes(q))continue;const r=document.createElement('tr');for(const [k] of keys)r.append(elem('td',x[k]??'Non attribué'));body.append(r)}if(!body.children.length){const r=document.createElement('tr'),td=elem('td','Aucun résultat.');td.colSpan=keys.length;r.append(td);body.append(r)}wrap.append(table);root.append(wrap)}}
$('control-currency').onchange=renderControl;$('control-search').oninput=renderControl;
async function load(){const e=++epoch;const r=await fetch('/api/admin/direction',{headers:{Authorization:'Bearer '+token}});const d=await r.json();if(!r.ok)throw Error(d.error);if(e!==epoch||!token)return;
 $('date').textContent='Situation au '+d.as_of;$('counts').replaceChildren();$('breakdown').replaceChildren();$('financial').replaceChildren();controlData=d.controlling;renderControl();
 for(const [key,name] of Object.entries(labels)){const values=d.counts[key];const card=elem('div',name);card.className='count';card.prepend(elem('strong',Object.values(values).reduce((a,b)=>a+b,0)));$('counts').append(card);const block=elem('div','');block.className='status-card';block.append(elem('h3',name));const sum=Object.values(values).reduce((a,b)=>a+b,0);for(const [s,n] of Object.entries(values)){const row=elem('div','');row.className='status-row';row.append(elem('span',s+' : '+n));const bar=document.createElement('progress');bar.max=Math.max(1,sum);bar.value=n;bar.setAttribute('aria-label',name+' — '+s);row.append(bar);block.append(row)}$('breakdown').append(block)}
 $('alerts').textContent=d.overdue+' relance(s) en retard ; '+d.ambiguous_opportunities+' opportunité(s) avec plusieurs devis acceptés, exclues des totaux.';
 for(const x of d.financial){const row=document.createElement('tr');for(const k of ['currency','count','revenue','direct_cost','margin'])row.append(elem('td',x[k]));$('financial').append(row)}
 if(!d.financial.length){const row=document.createElement('tr'),td=elem('td','Aucun engagement chiffrable.');td.colSpan=5;row.append(td);$('financial').append(row)}
}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();$('login').hidden=true;$('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
$('refresh').onclick=async()=>{try{await load();notice('Actualisé.')}catch(e){notice(e.message)}};
$('logout').onclick=()=>{epoch++;token='';controlData=null;for(const id of ['counts','breakdown','financial','date','alerts','control-tables'])$(id).replaceChildren();$('control-search').value='';$('control-currency').value='';$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};
